mapper.insert:
insert into sale(
	sale_no, sale_name, sale_category,
	sale_original_price, sale_discount_price,
	sale_content, sale_stock
)
values(
	#{saleNo}, #{saleName}, #{saleCategory},
	#{saleOriginalPrice}, #{saleDiscountPrice},
	#{saleContent}, #{saleStock}
)

mapper.select:
select S.sale_no, S.sale_name, S.sale_category, S.sale_original_price, S.sale_discount_price, T.attach_no from sale S left outer join sale_thumbnail T on S.sale_no = T.sale_no
and S.sale_category = #{saleCategory}
order by sale_no desc

select attach_no from sale_information
where sale_no = #{saleNo}
order by attach_no asc

select S.sale_no, S.sale_name, S.sale_category, S.sale_original_price, S.sale_discount_price, T.attach_no from sale S left outer join sale_thumbnail T on S.sale_no = T.sale_no where S.sale_no in (
#{saleNo}
) order by S.sale_no asc
